//	  )
//	  AND (
//	    $4::text IS NULL
//	    OR account_status = $4::text
//	  )
//	  AND deleted_at IS NULL
//	  AND tenant_id = current_tenant_id()
//	ORDER BY
//	  created_at DESC
//	LIMIT
//	  $1 OFFSET $2
func (q *Queries) ListUsers(ctx context.Context, arg ListUsersParams) ([]*User, error) {
	rows, err := q.db.Query(ctx, listUsers,
		arg.Limit,
		arg.Offset,
		arg.UserType,
		arg.AccountStatus,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*User{}
	for rows.Next() {
		var i User
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.EntityID,
			&i.PersonID,
			&i.EmployeeID,
			&i.Username,
			&i.Email,
			&i.PasswordHash,
			&i.UserType,
			&i.AccountStatus,
			&i.IsActive,
			&i.LastLoginAt,
			&i.PasswordChangedAt,
			&i.FailedLoginAttempts,
			&i.LockoutUntil,
			&i.SessionTimeoutMinutes,
			&i.MfaEnabled,
			&i.MfaSecret,
			&i.UserAttributes,
			&i.Settings,
			&i.Version,
			&i.LastValidationRun,
			&i.ValidationStatus,
			&i.ValidationErrors,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.PasswordStrength,
			&i.Compromised,
			&i.RotationRequired,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

